from rich.prompt import Prompt

def test_case_sensitive_true():
    print("Testing case_sensitive=True (default)...")
    # We need to mock input since Prompt.ask reads from stdin
    import builtins
    from unittest.mock import patch

    with patch('builtins.input', return_value='paul'):
        try:
            # This should fail because 'paul' is not in ['Paul', 'Jessica', 'Duncan']
            # But Prompt.ask is a loop, so it will keep asking.
            # To test this, we can't easily use Prompt.ask in a loop with patch.
            # Instead, we can test PromptBase.process_response directly.
            pass
        except Exception as e:
            print(f"Caught expected error: {e}")

def test_prompt_base_directly():
    from rich.prompt import PromptBase, InvalidResponse

    class TestPrompt(PromptBase[str]):
        pass

    # Case sensitive = True
    p_sensitive = TestPrompt(choices=["Paul", "Jessica"], case_sensitive=True)
    try:
        p_sensitive.process_response("paul")
        print("FAILED: 'paul' should be invalid when case_sensitive=True")
    except InvalidResponse:
        print("PASSED: 'paul' is invalid when case_sensitive=True")

    try:
        p_sensitive.process_response("Paul")
        print("PASSED: 'Paul' is valid when case_sensitive=True")
    except InvalidResponse:
        print("FAILED: 'Paul' should be valid when case_sensitive=True")

    # Case sensitive = False
    p_insensitive = TestPrompt(choices=["Paul", "Jessica"], case_sensitive=False)
    try:
        p_insensitive.process_response("paul")
        print("PASSED: 'paul' is valid when case_sensitive=False")
    except InvalidResponse:
        print("FAILED: 'paul' should be valid when case_sensitive=False")

    try:
        p_insensitive.process_response("PAUL")
        print("PASSED: 'PAUL' is valid when case_sensitive=False")
    except InvalidResponse:
        print("FAILED: 'PAUL' should be valid when case_sensitive=False")

    try:
        p_insensitive.process_response("Invalid")
        print("FAILED: 'Invalid' should be invalid when case_sensitive=False")
    except InvalidResponse:
        print("PASSED: 'Invalid' is invalid when case_sensitive=False")

if __name__ == "__main__":
    test_prompt_base_directly()
